<section class="section" id="lugares"><div class="sectionhead"><div><h2><?=e($t['directory_heading'])?> <?=e($name)?></h2></div></div><p class="directory-map"><a class="text-link" href="<?=e($map)?>" target="_blank" rel="noopener noreferrer"><?=e($t['map'])?></a></p><div id="catalogo-local" data-destino="<?=e($slug)?>"><div class="directory-tabs" role="tablist" aria-label="<?=e($t['directory'])?>"><button type="button" role="tab" id="directory-tab-todos" aria-selected="true" aria-controls="directory-panel" tabindex="0"><?=e($t['all'])?></button><?php foreach($d['categories'] as $category):?><button type="button" role="tab" id="directory-tab-<?=e($category['code'])?>" aria-selected="false" aria-controls="directory-panel" tabindex="-1" data-category="<?=e($category['code'])?>"><?=e(shortDirectoryCategory($category['code'],$category['label'],$locale))?></button><?php endforeach;?></div><div id="directory-panel" role="tabpanel" aria-labelledby="directory-tab-todos" tabindex="0"><?php if(!$d['businesses']):?><p class="directory-empty"><?=e($t['empty'])?></p><?php else:?><?php $directoryGroups=['page'=>['es'=>'Páginas comerciales','en'=>'Business pages','pt-BR'=>'Páginas comerciais'],'featured'=>['es'=>'Destacados','en'=>'Featured','pt-BR'=>'Destaques'],'basic'=>['es'=>'Otros negocios','en'=>'Other businesses','pt-BR'=>'Outros negócios'],'free'=>['es'=>'Listado gratuito','en'=>'Free listings','pt-BR'=>'Listagem gratuita']];foreach($directoryGroups as $tier=>$labels):$tierBusinesses=array_values(array_filter($d['businesses'],static fn($item)=>($tier==='page'?in_array($item['plan_code'],['page','page_premium'],true):$item['plan_code']===$tier)));if(!$tierBusinesses)continue;?><section class="directory-tier" data-directory-tier="<?=e($tier)?>" aria-labelledby="directory-heading-<?=e($tier)?>"><h3 class="directory-tier-heading" id="directory-heading-<?=e($tier)?>"><?=e($labels[$locale]??$labels['es'])?></h3><div class="directory-grid"><?php foreach($tierBusinesses as $business):require dirname($repositoryPath).'/views/directory-card.php'; ?><?php endforeach;?></div></section><?php endforeach;?><?php endif;?></div></div></section>
